INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Pré-Onboarding', 'Antes do D1', 1);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Recepção e Alinhamento Inicial na Unidade de Internação', 'D4 a D7', 2);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Integração e Desenvolvimento Inicial', 'D7 a D15', 3);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Consolidação da Adaptação', 'D15 a D30', 4);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Preparação para a Conversa de Desenvolvimento - D45', 'D30 a D44', 5);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Primeira Avaliação de Experiência', 'D40', 6);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Consolidação da Performance', 'D41 a D79', 7);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Avaliação Final do Período de Experiência', 'D80', 8);
INSERT INTO public.fases (nome, periodo, ordem) VALUES ('Encerramento da Jornada de Integração', 'D81 a D90', 9);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Receber as informações do novo colaborador pela área de Recrutamento e Seleção, se atentar a data de ínicio, jornada de trabalho, e informações relevantes sobre o novo colaborador.', 'Fique atento ao seu e-mail e contato com o Recrutador pelas nossas ferramentas oficiais de comunicação. É importante preparar a chegada do colaborador com antecedência, minimizando divergências no momento de recepcionar o novo colaborador.', NULL, 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Definir o Parceiro de Integração e fornecer as informações básicas do colaborador, como: função, data de inicio, horário de trabalho e informações relevantes para acompanhamento.', 'Escolha um profissional que tenha domínio da função do novo colaborador, com bom desempenho, disponibilidade e perfil colaborativo.', NULL, 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Solicite via chamado e/ou e-mail os acessos e demais itens do colaborador: crachá, uniformes, Login de rede, licença de pacote office, Notebook/Desktop, conforme a elegibilidade/função do colaborador. Em caso de dúvidas, acesse pelo Nossa Gente: https://nossagente.mybeehome.com/links', 'Cumpra no prazo os fluxos e processos que precisam ser realizados antes da chegada do novo colaborador. É imprescindivel garantir que o colaborador inicie a sua jornada com todos acessos, equipamentos e suprimentos necessários para realizar o seu trabalho.', NULL, 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Prepare a equipe para a chegada do novo colaborador.', 'Incentive todos a participarem do acolhimento e a promoverem um ambiente receptivo.', NULL, 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Preparar materiais e informações que serão utilizados na integração.', 'Separe procedimentos, fluxos, documentos e demais conteúdos que apoiarão o início das atividades. Isso facilitará as conversas de acompanhamento com o colaborador.', NULL, 5);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Tenha domínio sobre as atividades e responsabilidades do cargo.', 'Esteja preparado para esclarecer dúvidas iniciais e orientar a rotina de trabalho.', NULL, 6);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 1), 'Planejar os momentos de acompanhamento durante os primeiros 90 dias.', 'Reserve tempo na agenda para conversas, observações e feedbacks ao longo da jornada.', NULL, 7);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Recepcionar o colaborador na área', 'Reserve um momento exclusivo para dar as boas-vindas ao novo colaborador, em conjunto com o Parceiro de Integração e equipe.', 'Colaborador sente-se acolhido e valorizado pela equipe.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Apresentar a missão, objetivos e desafios da área. Utilize o template padrão disponibilizado pela área de Educação Corporativa.', 'Explicar como o trabalho da equipe contribui para os resultados da equipe, para o cliente final e introduzir o colaborador ao négócio.', 'Colaborador compreende o propósito da área.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Apresentar as expectativas da função e da jornada nos próximos 90 dias.', 'Esclareça responsabilidade, prioridades e como será o modelo de trabalho no período de Integração (primeiros 90 dias).', 'Colaborador compreende com clareza o que é esperado dele.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Alinhar a agenda e responsabilidades dos primeiros dias.', 'Explique os treinamentos que deverão ser realizados na Universidade Corporativa, reforce que todos os procedimentos deverão ser observados e depois acompanhados.', 'Treinamento concluídos dentro do prazo. Procedimentos mínimos referente ao Enfermeiro realizado.', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Apresentar o Parceiro de Integração e explicar o seu papel durante a jornada.', 'Reforce a importância de atuação do Parceiro de Integração e como será o seu apoio ao longo dos 90 dias.', 'Entendimento do Parceiro de Integração como ponto focal da sua jornada de aprendizagem na Hapvida.', 5);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Receber orientação:  sobre o uso de EPI´s,  higienização das mãos (LEITURA: meta 05 - POP - SCIH - 001 - HIGIENIZAÇÃO DAS MÃOS HAPVIDA e  PT - SCIRAS - 020 - PRECAUÇÕES E ISOLAMENTO) e adorno zero.', 'Reforce os pontos apresentados na integração assistencial e mostre onde estão os EPI''s do andar e como localizar os documentos no Interact', 'Utiliza os EPI''s de forma de correta e saber fazer busca de documentos', 6);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Compreender a rotina de organização do posto de enfermagem, expurgo e controle de entrega/recebimento de material à CME.', 'Reserve um momento para apresentar as rotinas da unidade de internação adulto.', 'Acompanhamento  e realização dos fluxos estabelecidos do setor', 7);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Aplicar o procedimento de identificação do paciente (META 01) - (LEITURA: POL - SP - 002 - POLÍTICA CORPORATIVA DE SEGURANÇA DO PACIENTE e POP - DI - 047 - PROTOCOLO DE IDENTIFICAÇÃO DO PACIENTE).', 'Reforçar a importância do conhecimento sobre a meta 01', 'Colaborador compreende o propósito da aplicação, garantindo segurança e qualidade no atendimento.', 8);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer sobre o protocolo de administração de medicamentos alta vigilância, dupla checagem, alergia (META 03) - (LEITURA: MAT - AF - 028 - MEDICAMENTO DE ALTA VIGILÂNCIA e POP - DI - 057 - USO DE DROGAS DE ALTO RISCO).', 'Reforçar a importância do conhecimento sobre a meta 03 referente a administração de medicamentos.', 'Colaborador compreende sobre o processo de administração segura de medicamentos.', 9);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer sobre o protocolo de cirurgia segura e preparo do paciente para cirurgia (META 04) - LEITURA: POP - SC - 001 - BANHO PRÉ OPERATÓRIO', 'Reforçar a importância do conhecimento sobre a meta 04 referente a cirurgia segura.', 'Colaborador compreende sobre o processo de cirurgia segura e banho pré-operatório.', 10);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer e Aplicar o Protocolo de prevenção de queda (META 06)', 'Demonstrar em sistema como realizar a avaliação de risco para queda.', 'Colaborador compreende como levantar os riscos e aplicar as medidas preventivas.', 11);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer e aplicar o protocolo de prevenção de lesão por pressão (META 06) - ( LEITURA: PT - ENF - 011 - PROTOCOLO PREVENÇÃO DE LESÃO POR PRESSÃO ADULTO e MAT - ENF - 006 - RELÓGIO DE DECÚBITO)', 'Demonstrar em sistema como realizar a avaliação de risco para LPP.', 'Colaborador compreende como levantar os riscos e aplicar as medidas preventivas.', 12);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer e aplicar as medidas de prevençao de ITU em pacientes com cateter vesical de demora (LEITURA:  PT - SCIRAS - 005 - PREVENÇÃO DE INFECÇÃO DE TRATO URINÁRIO).', 'Reforçar a importância do conhecimento sobre a prevenção de ITU.', 'Colaborador compreende como levantar os riscos e aplicar as medidas preventivas.', 13);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Apresentar e manusear o Sistema Prontuário Eletrônico do Paciente (PEP/ Siga PEP) com seu login e senha', 'Observe a evolução do colaborador na execução e manuseio do sistema prontuario eletrônico.', 'Realiza corretamente a prescrição de enfermagem, planejando cuidados e intervenções individualizadas, acompanha a prescrição médica, realiza aprazamento e checagem das medicações, efetua registro seguro na evolução de enfermagem, aplica escalas de cuidado individualizadas por paciente.', 14);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Compreender e acompanhar o time de técnicos de enfermagem na verificação dos sinais vitais 1/1 hora nas 24 dos pacientes pós cirúrgico/ alta da UTI', 'Verifique o cumprimento das checagens realizadas pelo enfermeiro', 'Acompanhamento contínuo registrado', 15);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Acompanhar rotinas de admissão dos pacientes e registros de enfermagem', 'Promova uma discussão após o acompanhamento de uma admissão guiada por um preceptor e acompanhamento do registro em sistema.', 'Colaborador coompreende a rotina de admissão e realiza em conjunto com preceptor o registro em sistema.', 16);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Conhecer e aplicar medidas de prevenção para infecção de corrente sanguínea a cateter venoso central e periférico. Rotina de troca de dispositivos e identificação (LEITURA: POP - ENF - 023 - PUNÇÃO VENOSA PERIFÉRICA e PT - SCIRAS - 019 - PREVENÇÃO DE INFECÇÃO DE CORRENTE SANGUÍNEA)', 'Conhecer sobre a árvore decisória de TIV, aplicar as medidas preventivas e conhecer os insumos.', 'Compreender que as medidas preventivas impactam na assistênica a saúde.', 17);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 2), 'Acompanhar e aplicar os pactos assistencias e projetos salvam vidas', 'Observe a evolução do colaborador na execução e na aplicação dos processos da área e o nível de autonomia demonstrado.', 'Possui conhecimento e aplica os 05 pactos assistenciais no seu dia a dia de trabalho (Escalonamento do risco assistencial; Segurança em primeiro lugar; Atitude de dono; Paciente no centro de tudo e Resolução de situações críticas).', 18);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Realizar conversas semanais de acompanhamento', 'Reserve um momento para ouvir o colaborador, compreender sua adaptação, esclarecer dúvidas e alinhar expectativas. Utilize perguntas abertas e pratique a escuta ativa para entender como está sendo sua experiência na Hapvida.', 'Colaborador compartilha sua percepção sobre a jornada de integração, demonstrando como está sua adaptação à função, à equipe e à rotina de trabalho. Relação de confiança fortalecida entre líder e colaborador.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Acompanhar a evolução técnica', 'Observe a evolução do colaborador na execução das atividades, na assimilação dos processos da área e na realização dos treinamentos obrigatórios e específicos. Considere também a qualidade das entregas, a aplicação dos conhecimentos adquiridos e o nível de autonomia demonstrado.', 'Evolução técnica compatível com a etapa da integração, evidenciada pela realização dos treinamentos previstos, domínio gradual das atividades e aumento da autonomia.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Acompanhar e realizar os procedimentos privativos do Enfermeiro da Unidade de Internação Aduldo (CVD, CVA, CNE, Gasometria Arterial, Coleta de exames por CVC,  instalação e cuidado com NPT)', 'Reserve um momento para acompanhar o preceptor durante a assistencia na realização dos procedimentos privativos do enfermeiro.', 'Colaborador demonstra participação ativa durante o acompanhamento dos procedimentos junto do preceptor.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Conhecer e realizar administração de dieta e medicamentos por via enteral (LEITURA: POP - NUTRI - 0012 - DIETA ENTERAL e MAN - AF - 012 - MANUAL DE ADMINISTRAÇÃO MEDICAMENTOS VIA SONDA)', 'Acompanhar o novo colabordor no processo de administração de medicamento por SNE.', 'Colaborador demonstra domínio sobre cuidados com SNE e administração de medicamentos.', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Aplicar a SAE (Sistematização da Assistência de Enfermagem)', 'Reforce a importância da aplicação da ferramenta visando garantir a qualidade na assistencia prestada', 'Realiza corretamente a Sistematização da Assistência de Enfermagem (SAE), incluindo avaliação de enfermagem, identificação de diagnósticos, planejamento, implementação das ações e evolução de enfermagem, garantindo registro adequado, continuidade do cuidado e segurança do paciente.', 5);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Realizar a avaliação de risco assistencial', 'Observe a evolução do colaborador na execução das atividades e a aplicação dos conhecimentos adquiridos e o nível de autonomia demonstrado.', 'Realiza corretamente a avaliação de risco assistencial, identificando fatores de risco para broncoaspiração, tromboembolismo venoso (TEV) e flebite, implementando medidas preventivas adequadas e garantindo segurança e cuidado proativo ao paciente.', 6);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Aplicar checklist e acompanhar rotina do transporte seguro', 'Reforçe a importância da aplicação do checklist e o acompanhamento do fluxo (origem e destino).', 'Realiza corretamente a aplicação do checklist de transporte garantindo o transporte seguro do paciente.', 7);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 3), 'Fornecer feedback contínuo', 'Compartilhe feedbacks frequentes, reconhecendo avanços e orientando melhorias com base em situações observadas. Defina ações práticas para apoiar a evolução do colaborador.', 'Colaborador compreende seus pontos fortes, as oportunidades de desenvolvimento e as expectativas para sua evolução ao longo da integração.', 8);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Avaliar a evolução da adaptação', 'Observe a segurança, qualidade e organização do colaborador na execução das atividades.', 'Colaborador demonstra maior independência para executar as suas atividades, com menor supervisão do líder e/ou parceiro de integração.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Estimular a participação de reuniões e/ou projetos', 'Promova a oportunidade de interação com as demais equipes e projetos que façam sentido com as competências apresentadas pelo colaborador.', 'Participação ativa nas demandas, atividades e projetos da equipe. Contribuições que são relevantes para o time. Ideias que fazem sentido para o período de integração.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Identificar oportunidades de desenvolvimento', 'A partir dos feedbacks semanais e acompanhamento com o Parceiro de Integração, observe lacunas técnicas e/ou comportamentais.', 'Ações de desenvolvimento estruturadas, que possibilitem o crescimento gradativo do colaborador na função.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Realizar conversa estruturada de acompanhamento', 'Conduza a conversa com escuta ativa, fazendo perguntas abertas que incentivem o colaborador a refletir sobre sua experiência. Evite interromper ou antecipar respostas e aprofunde a conversa para identificar percepções, necessidades e oportunidades de desenvolvimento.', 'Percepções, feedbacks e ações acordadas registrados no checklist e/ou no Diário de Bordo do colaborador na plataforma LG Lugar de Gente, assegurando o acompanhamento da evolução durante a jornada de integração.', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Acompanhar a passagem de plantão método SBAR (LEITURA:  POP - ENF - 007 - PASSAGEM DE PLANTÃO) e visita multiprofissional (META 02).', 'Promova a participação ativa do colaborador no momento de troca de plantão.', 'Colaborador mantem a comunicação direta, focada e sem interrupções. Confirme se o profissional que está recebendo o plantão compreendeu as pendências críticas', 5);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Conhecer e acompanhar uma hemotransfusão (LEITURA: PT - AH - 002 - PROTOLO TRANSFUSIONAL,  FORM - AH - 001 - ACOMPANHAMENTO TRANSFUSIONAL e MAT - AH - 002 - REAÇÃO TRANSFUSIONAL 2024)', 'Promover a participação do colaborador na dupla checagem do hemocomponente.', 'Acompanhar a excecução do protocolo de infusão do hemocomponente e conduta frente a reação adversa.', 6);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Aplicar os Protocolos assistenciais (Sepse, Dor Torácica, AVC e TEV)', 'Avalie o conhecimento técnico, identificando pontos de fortalecimento e melhoria.', 'Evolução observada no conhecimento dos protocolos assistenciais.', 7);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Conhecer e manusear os equipamentos do setor (ECG, bomba infusora, cardioversor, aspirador)', 'Demonstrar o funcionamento de cada equipamento.', 'Evolução esperado o manuseio dos equipamentos críticos do setor.', 8);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 4), 'Conduzir o Time de Resposta rápida (código azul e código amarelo)', 'Observe a evolução do colaborador na execução das atividades e a aplicação do código seguindo os critérios de eligibilidade.', 'Reconhece sinais de deterioração clínica do paciente e realiza corretamente o acionamento do Código Amarelo e Azul via mobile, seguindo os protocolos institucionais, garantindo resposta rápida e segura para a equipe e o paciente.', 9);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Consolidar evidências de desempenho', 'Reúna exemplos de entregas, comportamentos e evolução observados durante a integração.', 'Avaliação baseada em fatos e evidências.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Reunir informações com o Parceiro de Integração', 'Converse sobre a evolução técnica, adaptação, autonomia e relacionamento do colaborador.', 'Visão compartilhada entre líder e Parceiro de Integração sobre a evolução do colaborador.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Validar treinamentos e adaptação', 'Verifique a conclusão dos treinamentos e como os conhecimentos estão sendo aplicados na rotina.', 'Treinamentos concluídos e evolução compatível com a etapa da integração.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Identificar oportunidades de desenvolvimento', 'Avalie competências técnicas e comportamentais, identificando pontos de fortalecimento e melhoria.', 'Oportunidades de desenvolvimento definidas com base em evidências.', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Preparar o feedback de D40', 'Estruture os principais avanços, oportunidades e próximos passos da jornada.', 'Feedback organizado, objetivo e consistente.', 5);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 5), 'Planejar ações para a próxima etapa', 'Caso necessário, defina ações de desenvolvimento para apoiar a evolução do colaborador após o D45.', 'Próximos passos alinhados e plano de desenvolvimento definido, quando aplicável.', 6);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 6), 'Conduzir a conversa de reflexão dos primeiros 40 dias', 'Promova um diálogo transparente e equilibrado e busque as percepções do colaborador de como está sendo a sua jornada. Reflitam sobre a adaptação a equipe, as áreas parceiras, suporte do Parceiro de Integração e da própria liderança.', 'Experiência do colaborador compreendida e registrada, com alinhamento entre líder e colaborador sobre a adaptação, o suporte recebido e as ações necessárias para fortalecer sua integração e desenvolvimento.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 6), 'Compartilhar pontos fortes e oportunidades de desenvolvimento', 'Basei-se em fatos para comemorar o decorrer da jornada e principais acertos. Corrija rota caso sejam identificadas oportunidades de desenvolvimento.', 'Avanços reconhecidos e oportunidades de desenvolvimento alinhadas, com expectativas claras e ações definidas para apoiar a evolução do colaborador.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 6), 'Reforçar os objetivos para o próximo ciclo de Integração', 'Alinhe as expectativas para o próximo ciclo da integração, esclarecendo prioridades, comportamentos esperados e objetivos de desenvolvimento. Incentive o colaborador a assumir um papel ativo em sua evolução.', 'Alinhe as expectativas para o próximo ciclo da integração, esclarecendo prioridades, comportamentos esperados e objetivos de desenvolvimento. Incentive o colaborador a assumir um papel ativo em sua evolução.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 7), 'Delegar atividades de maior complexidade.', 'Amplie gradualmente o nível de responsabilidade.', 'Colaborador demonstra evolução técnica.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 7), 'Realizar reuniões periódicas de acompanhamento.', 'Mantenha conversas sobre prioridades, desempenho e desenvolvimento.', 'Acompanhamento contínuo registrado', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 7), 'Monitorar o plano de ação, quando houver.', 'Verifique o cumprimento das ações definidas no D45', 'Evolução observada nos pontos priorizados', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 7), 'Reconhecer avanços.', 'Valorize conquistas e comportamentos alinhados à cultura Hapvida.', 'Colaborador demonstra maios engajamento', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 8), 'Retomar a jornada dos primeiros 80 dias', 'Relembre os principais momentos do período: integração, entregas realizadas, desafios enfrentados e aprendizados. Crie um ambiente de abertura para uma conversa de mão dupla.', 'Colaborador compartilha sua percepção sobre a experiência, adaptação ao time, rotina, desafios e aprendizados.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 8), 'Avaliar desempenho e aderência ao papel', 'Apresente uma avaliação equilibrada considerando entregas, comportamentos, competências, relacionamento com o time e alinhamento aos valores da empresa. Traga exemplos concretos.', 'Feedback estruturado com exemplos e percepções alinhadas entre líder e liderado.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 8), 'Reconhecer contribuições e avanços', 'Valorize conquistas, atitudes positivas e comportamentos que devem ser mantidos. Reforce o impacto gerado pelo colaborador desde sua entrada.', 'Reconhecimento registrado e motivadores identificados para continuidade do desenvolvimento.', 3);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 8), 'Construir plano de desenvolvimento (quando aplicável)', 'Em conjunto com o colaborador, defina competências a desenvolver, objetivos, ações práticas e formas de acompanhamento.', 'Colaborador participa da construção do próprio desenvolvimento e assume compromissos para o próximo ciclo.', 4);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 9), 'Realizar a conversa de encerramento da integração.', 'Reflita sobre a jornada, reconheça conquistas e reforce o compromisso com o desenvolvimento contínuo.', 'Colaborador sente-se integrado e preparado para a próxima etapa.', 1);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 9), 'Compartilhar os próximos passos de desenvolvimento.', 'Explique como ocorrerão os ciclos de desempenho, treinamentos e acompanhamento da liderança.', 'Colaborador compreende sua jornada após os 90 dias.', 2);
INSERT INTO public.atividades_modelo (fase_id, atividade, como_conduzir, evidencia_esperada, ordem) VALUES ((SELECT id FROM public.fases WHERE ordem = 9), 'Estimular o protagonismo no desenvolvimento.', 'Reforce a importância da aprendizagem contínua, da busca por feedback e do alinhamento aos valores da Hapvida.', 'Colaborador demonstra comprometimento com seu desenvolvimento futuro.', 3);